import{J as e,n as t,ot as n,q as r}from"./chunks/framework.CU_ytobU.js";var i=JSON.parse(`{"title":"@jsprismarine/nethernet","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"@jsprismarine/nethernet"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/nethernet/"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/nethernet/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/nethernet/src"}},"headers":[],"relativePath":"api/@jsprismarine/nethernet/index.md","filePath":"api/@jsprismarine/nethernet/index.md","lastUpdated":1794343625000}`),a={name:`api/@jsprismarine/nethernet/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../">JSPrismarine</a> / @jsprismarine/nethernet</p><h1 id="jsprismarine-nethernet" tabindex="-1">@jsprismarine/nethernet <a class="header-anchor" href="#jsprismarine-nethernet" aria-label="Permalink to “@jsprismarine/nethernet”">​</a></h1><p><a href="https://discord.gg/kZZCDyCBbW" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/704967868885762108?color=%237289DA&amp;label=Discord" alt="Join the Discord Server"></a><a href="https://www.npmjs.com/package/@jsprismarine/nethernet" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/@jsprismarine/nethernet" alt="npm"></a></p><p>NetherNet is the WebRTC transport Minecraft: Bedrock Edition uses beside RakNet. This package holds what a server and a client both need on top of <a href="https://www.npmjs.com/package/nethernet" target="_blank" rel="noreferrer"><code>nethernet</code></a>, which carries the WebRTC connection itself:</p><ul><li><code>HttpSignaling</code>, the HTTP signaling a client joining by address uses: <code>GET /v1/join</code> for the server&#39;s status and <code>POST /v1/join/{networkId}</code> to trade an SDP offer for an answer.</li><li><code>NetherNetIdentity</code>, which signs the <code>a=identity</code> a client requires on every answer, and the SDP helpers it is built on.</li><li><code>encodeLanAdvertisement</code> and <code>decodeLanAdvertisement</code>, the advertisement a server answers LAN discovery with, on the fixed UDP port <code>NETHERNET_LAN_PORT</code>.</li><li><code>compactEs384</code>, <code>detachedEs384</code> and <code>verifiesDetachedEs384</code>, the ES384 JSON Web Signatures Bedrock signs its tokens with, made and checked by <a href="https://github.com/panva/jose" target="_blank" rel="noreferrer"><code>jose</code></a>.</li></ul><p>It knows nothing about Minecraft packets. The <code>0xFE</code> batch id NetherNet leaves out of each message is the business of whichever transport carries batches over it.</p><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to “Classes”">​</a></h2><ul><li><a href="./classes/HttpSignaling.html">HttpSignaling</a></li><li><a href="./classes/JoinRefusedError.html">JoinRefusedError</a></li><li><a href="./classes/NetherNetIdentity.html">NetherNetIdentity</a></li></ul><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><h3 id="httpsignalingoptions" tabindex="-1">HttpSignalingOptions <a class="header-anchor" href="#httpsignalingoptions" aria-label="Permalink to “HttpSignalingOptions”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L36" target="_blank" rel="noreferrer">HttpSignaling.ts:36</a></p><p>What the signaling server needs besides the answerer.</p><h4 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h4><h5 id="answerer" tabindex="-1">answerer <a class="header-anchor" href="#answerer" aria-label="Permalink to “answerer”">​</a></h5><blockquote><p><code>readonly</code> <strong>answerer</strong>: <a href="#nethernetofferanswerer"><code>NetherNetOfferAnswerer</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L38" target="_blank" rel="noreferrer">HttpSignaling.ts:38</a></p><p>Turns an offer into an answer and keeps the peer it negotiates.</p><h5 id="answertimeoutms" tabindex="-1">answerTimeoutMs? <a class="header-anchor" href="#answertimeoutms" aria-label="Permalink to “answerTimeoutMs?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>answerTimeoutMs?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L45" target="_blank" rel="noreferrer">HttpSignaling.ts:45</a></p><p>How long an offer may wait for its answer.</p><h5 id="logger" tabindex="-1">logger <a class="header-anchor" href="#logger" aria-label="Permalink to “logger”">​</a></h5><blockquote><p><code>readonly</code> <strong>logger</strong>: <a href="#signalinglogger"><code>SignalingLogger</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L43" target="_blank" rel="noreferrer">HttpSignaling.ts:43</a></p><h5 id="sign" tabindex="-1">sign <a class="header-anchor" href="#sign" aria-label="Permalink to “sign”">​</a></h5><blockquote><p><code>readonly</code> <strong>sign</strong>: (<code>answer</code>) =&gt; <code>string</code> | <code>Promise</code>&lt;<code>string</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L42" target="_blank" rel="noreferrer">HttpSignaling.ts:42</a></p><p>Adds the server&#39;s <code>a=identity</code> to an answer; the client refuses one without it.</p><h6 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="answer" tabindex="-1">answer <a class="header-anchor" href="#answer" aria-label="Permalink to “answer”">​</a></h6><p><code>string</code></p><h6 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h6><p><code>string</code> | <code>Promise</code>&lt;<code>string</code>&gt;</p><h5 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h5><blockquote><p><code>readonly</code> <strong>status</strong>: () =&gt; <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L40" target="_blank" rel="noreferrer">HttpSignaling.ts:40</a></p><p>The <code>GET /v1/join</code> body, read per request.</p><h6 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h6><p><code>string</code></p><hr><h3 id="joinprobe" tabindex="-1">JoinProbe <a class="header-anchor" href="#joinprobe" aria-label="Permalink to “JoinProbe”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/joinByAddress.ts#L25" target="_blank" rel="noreferrer">joinByAddress.ts:25</a></p><p>What <code>GET /v1/join</code> said about a server that speaks NetherNet.</p><h4 id="properties-1" tabindex="-1">Properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to “Properties”">​</a></h4><h5 id="status-1" tabindex="-1">status? <a class="header-anchor" href="#status-1" aria-label="Permalink to “status?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>status?</strong>: <a href="#nethernetstatus"><code>NetherNetStatus</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/joinByAddress.ts#L30" target="_blank" rel="noreferrer">joinByAddress.ts:30</a></p><p>The server&#39;s status, when it sent one. Bedrock Dedicated Server 1.26.51 answers with an empty body when LAN visibility is off, and go-nethernet does when it has no status to give.</p><hr><h3 id="lanadvertisement" tabindex="-1">LanAdvertisement <a class="header-anchor" href="#lanadvertisement" aria-label="Permalink to “LanAdvertisement”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L14" target="_blank" rel="noreferrer">LanAdvertisement.ts:14</a></p><p>What a server tells a client looking for games on the local network, in the answer to a NetherNet discovery request on UDP 7551. The client lists it among its LAN games.</p><h4 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to “Extends”">​</a></h4><ul><li><a href="#nethernetstatus"><code>NetherNetStatus</code></a></li></ul><h4 id="properties-2" tabindex="-1">Properties <a class="header-anchor" href="#properties-2" aria-label="Permalink to “Properties”">​</a></h4><h5 id="acceptsonlineauth" tabindex="-1">acceptsOnlineAuth <a class="header-anchor" href="#acceptsonlineauth" aria-label="Permalink to “acceptsOnlineAuth”">​</a></h5><blockquote><p><code>readonly</code> <strong>acceptsOnlineAuth</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L18" target="_blank" rel="noreferrer">LanAdvertisement.ts:18</a></p><p>Whether a client signed in to Xbox Live may join.</p><h5 id="acceptsselfsignedauth" tabindex="-1">acceptsSelfSignedAuth <a class="header-anchor" href="#acceptsselfsignedauth" aria-label="Permalink to “acceptsSelfSignedAuth”">​</a></h5><blockquote><p><code>readonly</code> <strong>acceptsSelfSignedAuth</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L20" target="_blank" rel="noreferrer">LanAdvertisement.ts:20</a></p><p>Whether a client that signs its own login may join, which an online-mode server refuses.</p><h5 id="connectiontype" tabindex="-1">connectionType <a class="header-anchor" href="#connectiontype" aria-label="Permalink to “connectionType”">​</a></h5><blockquote><p><code>readonly</code> <strong>connectionType</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L23" target="_blank" rel="noreferrer">LanAdvertisement.ts:23</a></p><h5 id="editorworld" tabindex="-1">editorWorld <a class="header-anchor" href="#editorworld" aria-label="Permalink to “editorWorld”">​</a></h5><blockquote><p><code>readonly</code> <strong>editorWorld</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L15" target="_blank" rel="noreferrer">LanAdvertisement.ts:15</a></p><h5 id="gametype" tabindex="-1">gameType <a class="header-anchor" href="#gametype" aria-label="Permalink to “gameType”">​</a></h5><blockquote><p><code>readonly</code> <strong>gameType</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L16" target="_blank" rel="noreferrer">NetherNetStatus.ts:16</a></p><p>The <code>Gametype</code> id: 0 survival, 1 creative, 2 adventure.</p><h6 id="inherited-from" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a>.<a href="#gametype-1"><code>gameType</code></a></p><h5 id="hardcore" tabindex="-1">hardcore <a class="header-anchor" href="#hardcore" aria-label="Permalink to “hardcore”">​</a></h5><blockquote><p><code>readonly</code> <strong>hardcore</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L16" target="_blank" rel="noreferrer">LanAdvertisement.ts:16</a></p><h5 id="levelname" tabindex="-1">levelName <a class="header-anchor" href="#levelname" aria-label="Permalink to “levelName”">​</a></h5><blockquote><p><code>readonly</code> <strong>levelName</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L9" target="_blank" rel="noreferrer">NetherNetStatus.ts:9</a></p><h6 id="inherited-from-1" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-1" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a>.<a href="#levelname-1"><code>levelName</code></a></p><h5 id="maxplayers" tabindex="-1">maxPlayers <a class="header-anchor" href="#maxplayers" aria-label="Permalink to “maxPlayers”">​</a></h5><blockquote><p><code>readonly</code> <strong>maxPlayers</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L14" target="_blank" rel="noreferrer">NetherNetStatus.ts:14</a></p><h6 id="inherited-from-2" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-2" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a>.<a href="#maxplayers-1"><code>maxPlayers</code></a></p><h5 id="motd" tabindex="-1">motd <a class="header-anchor" href="#motd" aria-label="Permalink to “motd”">​</a></h5><blockquote><p><code>readonly</code> <strong>motd</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L8" target="_blank" rel="noreferrer">NetherNetStatus.ts:8</a></p><h6 id="inherited-from-3" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-3" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a>.<a href="#motd-1"><code>motd</code></a></p><h5 id="nonce" tabindex="-1">nonce <a class="header-anchor" href="#nonce" aria-label="Permalink to “nonce”">​</a></h5><blockquote><p><code>readonly</code> <strong>nonce</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L22" target="_blank" rel="noreferrer">LanAdvertisement.ts:22</a></p><p>A random token per server start; Bedrock Dedicated Server sends 64 random bits in hex.</p><h5 id="playercount" tabindex="-1">playerCount <a class="header-anchor" href="#playercount" aria-label="Permalink to “playerCount”">​</a></h5><blockquote><p><code>readonly</code> <strong>playerCount</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L13" target="_blank" rel="noreferrer">NetherNetStatus.ts:13</a></p><h6 id="inherited-from-4" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-4" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a>.<a href="#playercount-1"><code>playerCount</code></a></p><h5 id="protocol" tabindex="-1">protocol <a class="header-anchor" href="#protocol" aria-label="Permalink to “protocol”">​</a></h5><blockquote><p><code>readonly</code> <strong>protocol</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L10" target="_blank" rel="noreferrer">NetherNetStatus.ts:10</a></p><h6 id="inherited-from-5" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-5" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a>.<a href="#protocol-1"><code>protocol</code></a></p><h5 id="version" tabindex="-1">version <a class="header-anchor" href="#version" aria-label="Permalink to “version”">​</a></h5><blockquote><p><code>readonly</code> <strong>version</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L12" target="_blank" rel="noreferrer">NetherNetStatus.ts:12</a></p><p>The game version, such as <code>1.26.51</code>.</p><h6 id="inherited-from-6" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-6" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a>.<a href="#version-1"><code>version</code></a></p><hr><h3 id="nethernetidentityoptions" tabindex="-1">NetherNetIdentityOptions <a class="header-anchor" href="#nethernetidentityoptions" aria-label="Permalink to “NetherNetIdentityOptions”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L32" target="_blank" rel="noreferrer">NetherNetIdentity.ts:32</a></p><p>How a <a href="./classes/NetherNetIdentity.html">NetherNetIdentity</a> presents itself.</p><h4 id="properties-3" tabindex="-1">Properties <a class="header-anchor" href="#properties-3" aria-label="Permalink to “Properties”">​</a></h4><h5 id="domain" tabindex="-1">domain? <a class="header-anchor" href="#domain" aria-label="Permalink to “domain?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>domain?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L34" target="_blank" rel="noreferrer">NetherNetIdentity.ts:34</a></p><p>Shown to players on first use over plain HTTP. Bedrock Dedicated Server says <code>self</code>.</p><h5 id="keyformat" tabindex="-1">keyFormat? <a class="header-anchor" href="#keyformat" aria-label="Permalink to “keyFormat?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>keyFormat?</strong>: <a href="#identitykeyformat"><code>IdentityKeyFormat</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L36" target="_blank" rel="noreferrer">NetherNetIdentity.ts:36</a></p><p>How the token carries the public key; a server&#39;s is a JWK, a client&#39;s base64 DER.</p><h5 id="now" tabindex="-1">now? <a class="header-anchor" href="#now" aria-label="Permalink to “now?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>now?</strong>: () =&gt; <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L38" target="_blank" rel="noreferrer">NetherNetIdentity.ts:38</a></p><p>The clock, in milliseconds since the epoch.</p><h6 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h6><p><code>number</code></p><h5 id="token" tabindex="-1">token? <a class="header-anchor" href="#token" aria-label="Permalink to “token?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>token?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L44" target="_blank" rel="noreferrer">NetherNetIdentity.ts:44</a></p><p>A token an authority issued for this key, used instead of a self-signed one: a signed-in client&#39;s multiplayer token from Minecraft&#39;s authorization service, whose <code>cpk</code> claim names this key. The fingerprints are still signed with the key here.</p><hr><h3 id="nethernetofferanswerer" tabindex="-1">NetherNetOfferAnswerer <a class="header-anchor" href="#nethernetofferanswerer" aria-label="Permalink to “NetherNetOfferAnswerer”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L20" target="_blank" rel="noreferrer">HttpSignaling.ts:20</a></p><p>The part of <code>nethernet</code>&#39;s <code>Server</code> that turns an offer into an answer.</p><h4 id="properties-4" tabindex="-1">Properties <a class="header-anchor" href="#properties-4" aria-label="Permalink to “Properties”">​</a></h4><h5 id="connections" tabindex="-1">connections <a class="header-anchor" href="#connections" aria-label="Permalink to “connections”">​</a></h5><blockquote><p><code>readonly</code> <strong>connections</strong>: <code>ReadonlyMap</code>&lt;<code>bigint</code>, { <code>rtcConnection?</code>: <code>unknown</code>; <code>close</code>(<code>reason?</code>): <code>void</code>; }&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L22" target="_blank" rel="noreferrer">HttpSignaling.ts:22</a></p><p>Every peer by connection ID, which a new offer&#39;s ID must not collide with.</p><h4 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h4><h5 id="handleoffer" tabindex="-1">handleOffer() <a class="header-anchor" href="#handleoffer" aria-label="Permalink to “handleOffer()”">​</a></h5><blockquote><p><strong>handleOffer</strong>(<code>signal</code>, <code>respond</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L24" target="_blank" rel="noreferrer">HttpSignaling.ts:24</a></p><p>Negotiates a peer for the offer, answering through <code>respond</code>.</p><h6 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="signal" tabindex="-1">signal <a class="header-anchor" href="#signal" aria-label="Permalink to “signal”">​</a></h6><p><code>SignalStructure</code></p><h6 id="respond" tabindex="-1">respond <a class="header-anchor" href="#respond" aria-label="Permalink to “respond”">​</a></h6><p>(<code>signal</code>) =&gt; <code>void</code></p><h6 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h6><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="nethernetstatus" tabindex="-1">NetherNetStatus <a class="header-anchor" href="#nethernetstatus" aria-label="Permalink to “NetherNetStatus”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L7" target="_blank" rel="noreferrer">NetherNetStatus.ts:7</a></p><p>What a NetherNet client is told about a server before it joins: the LAN advertisement on UDP 7551 and the <code>GET /v1/join</code> answer on the game port both carry these.</p><h4 id="extended-by" tabindex="-1">Extended by <a class="header-anchor" href="#extended-by" aria-label="Permalink to “Extended by”">​</a></h4><ul><li><a href="#lanadvertisement"><code>LanAdvertisement</code></a></li></ul><h4 id="properties-5" tabindex="-1">Properties <a class="header-anchor" href="#properties-5" aria-label="Permalink to “Properties”">​</a></h4><h5 id="gametype-1" tabindex="-1">gameType <a class="header-anchor" href="#gametype-1" aria-label="Permalink to “gameType”">​</a></h5><blockquote><p><code>readonly</code> <strong>gameType</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L16" target="_blank" rel="noreferrer">NetherNetStatus.ts:16</a></p><p>The <code>Gametype</code> id: 0 survival, 1 creative, 2 adventure.</p><h5 id="levelname-1" tabindex="-1">levelName <a class="header-anchor" href="#levelname-1" aria-label="Permalink to “levelName”">​</a></h5><blockquote><p><code>readonly</code> <strong>levelName</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L9" target="_blank" rel="noreferrer">NetherNetStatus.ts:9</a></p><h5 id="maxplayers-1" tabindex="-1">maxPlayers <a class="header-anchor" href="#maxplayers-1" aria-label="Permalink to “maxPlayers”">​</a></h5><blockquote><p><code>readonly</code> <strong>maxPlayers</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L14" target="_blank" rel="noreferrer">NetherNetStatus.ts:14</a></p><h5 id="motd-1" tabindex="-1">motd <a class="header-anchor" href="#motd-1" aria-label="Permalink to “motd”">​</a></h5><blockquote><p><code>readonly</code> <strong>motd</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L8" target="_blank" rel="noreferrer">NetherNetStatus.ts:8</a></p><h5 id="playercount-1" tabindex="-1">playerCount <a class="header-anchor" href="#playercount-1" aria-label="Permalink to “playerCount”">​</a></h5><blockquote><p><code>readonly</code> <strong>playerCount</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L13" target="_blank" rel="noreferrer">NetherNetStatus.ts:13</a></p><h5 id="protocol-1" tabindex="-1">protocol <a class="header-anchor" href="#protocol-1" aria-label="Permalink to “protocol”">​</a></h5><blockquote><p><code>readonly</code> <strong>protocol</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L10" target="_blank" rel="noreferrer">NetherNetStatus.ts:10</a></p><h5 id="version-1" tabindex="-1">version <a class="header-anchor" href="#version-1" aria-label="Permalink to “version”">​</a></h5><blockquote><p><code>readonly</code> <strong>version</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L12" target="_blank" rel="noreferrer">NetherNetStatus.ts:12</a></p><p>The game version, such as <code>1.26.51</code>.</p><hr><h3 id="portmapping" tabindex="-1">PortMapping <a class="header-anchor" href="#portmapping" aria-label="Permalink to “PortMapping”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L8" target="_blank" rel="noreferrer">udpPorts.ts:8</a></p><p>A NAT or port-forwarding mapping: clients reach <code>internal</code> through <code>external</code>.</p><h4 id="properties-6" tabindex="-1">Properties <a class="header-anchor" href="#properties-6" aria-label="Permalink to “Properties”">​</a></h4><h5 id="address" tabindex="-1">address? <a class="header-anchor" href="#address" aria-label="Permalink to “address?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>address?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L10" target="_blank" rel="noreferrer">udpPorts.ts:10</a></p><p>The address clients connect to, or undefined to keep each candidate&#39;s own address.</p><h5 id="external" tabindex="-1">external <a class="header-anchor" href="#external" aria-label="Permalink to “external”">​</a></h5><blockquote><p><code>readonly</code> <strong>external</strong>: <a href="#portrange"><code>PortRange</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L11" target="_blank" rel="noreferrer">udpPorts.ts:11</a></p><h5 id="internal" tabindex="-1">internal <a class="header-anchor" href="#internal" aria-label="Permalink to “internal”">​</a></h5><blockquote><p><code>readonly</code> <strong>internal</strong>: <a href="#portrange"><code>PortRange</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L12" target="_blank" rel="noreferrer">udpPorts.ts:12</a></p><hr><h3 id="portrange" tabindex="-1">PortRange <a class="header-anchor" href="#portrange" aria-label="Permalink to “PortRange”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L2" target="_blank" rel="noreferrer">udpPorts.ts:2</a></p><p>An inclusive range of UDP ports.</p><h4 id="properties-7" tabindex="-1">Properties <a class="header-anchor" href="#properties-7" aria-label="Permalink to “Properties”">​</a></h4><h5 id="end" tabindex="-1">end <a class="header-anchor" href="#end" aria-label="Permalink to “end”">​</a></h5><blockquote><p><code>readonly</code> <strong>end</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L4" target="_blank" rel="noreferrer">udpPorts.ts:4</a></p><h5 id="start" tabindex="-1">start <a class="header-anchor" href="#start" aria-label="Permalink to “start”">​</a></h5><blockquote><p><code>readonly</code> <strong>start</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L3" target="_blank" rel="noreferrer">udpPorts.ts:3</a></p><hr><h3 id="sdpfingerprint" tabindex="-1">SdpFingerprint <a class="header-anchor" href="#sdpfingerprint" aria-label="Permalink to “SdpFingerprint”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/sdp.ts#L12" target="_blank" rel="noreferrer">sdp.ts:12</a></p><p>One <code>a=fingerprint</code> attribute: the DTLS certificate hash the peer must present.</p><h4 id="properties-8" tabindex="-1">Properties <a class="header-anchor" href="#properties-8" aria-label="Permalink to “Properties”">​</a></h4><h5 id="algorithm" tabindex="-1">algorithm <a class="header-anchor" href="#algorithm" aria-label="Permalink to “algorithm”">​</a></h5><blockquote><p><code>readonly</code> <strong>algorithm</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/sdp.ts#L14" target="_blank" rel="noreferrer">sdp.ts:14</a></p><p>The hash function, such as <code>sha-256</code>.</p><h5 id="digest" tabindex="-1">digest <a class="header-anchor" href="#digest" aria-label="Permalink to “digest”">​</a></h5><blockquote><p><code>readonly</code> <strong>digest</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/sdp.ts#L16" target="_blank" rel="noreferrer">sdp.ts:16</a></p><p>The hash, colon-separated hex, as the SDP spells it.</p><hr><h3 id="signalingaddress" tabindex="-1">SignalingAddress <a class="header-anchor" href="#signalingaddress" aria-label="Permalink to “SignalingAddress”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/joinByAddress.ts#L5" target="_blank" rel="noreferrer">joinByAddress.ts:5</a></p><p>Where a NetherNet server signals: the TCP side of its game port.</p><h4 id="properties-9" tabindex="-1">Properties <a class="header-anchor" href="#properties-9" aria-label="Permalink to “Properties”">​</a></h4><h5 id="host" tabindex="-1">host <a class="header-anchor" href="#host" aria-label="Permalink to “host”">​</a></h5><blockquote><p><code>readonly</code> <strong>host</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/joinByAddress.ts#L6" target="_blank" rel="noreferrer">joinByAddress.ts:6</a></p><h5 id="port" tabindex="-1">port <a class="header-anchor" href="#port" aria-label="Permalink to “port”">​</a></h5><blockquote><p><code>readonly</code> <strong>port</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/joinByAddress.ts#L7" target="_blank" rel="noreferrer">joinByAddress.ts:7</a></p><hr><h3 id="signalinglogger" tabindex="-1">SignalingLogger <a class="header-anchor" href="#signalinglogger" aria-label="Permalink to “SignalingLogger”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L28" target="_blank" rel="noreferrer">HttpSignaling.ts:28</a></p><p>Where the signaling server reports what went wrong. <code>@jsprismarine/logger</code>&#39;s <code>Logger</code> fits.</p><h4 id="methods-1" tabindex="-1">Methods <a class="header-anchor" href="#methods-1" aria-label="Permalink to “Methods”">​</a></h4><h5 id="debug" tabindex="-1">debug() <a class="header-anchor" href="#debug" aria-label="Permalink to “debug()”">​</a></h5><blockquote><p><strong>debug</strong>(<code>message</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L29" target="_blank" rel="noreferrer">HttpSignaling.ts:29</a></p><h6 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h6><p><code>string</code></p><h6 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><h5 id="error" tabindex="-1">error() <a class="header-anchor" href="#error" aria-label="Permalink to “error()”">​</a></h5><blockquote><p><strong>error</strong>(<code>error</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L32" target="_blank" rel="noreferrer">HttpSignaling.ts:32</a></p><h6 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="error-1" tabindex="-1">error <a class="header-anchor" href="#error-1" aria-label="Permalink to “error”">​</a></h6><p><code>unknown</code></p><h6 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><h5 id="info" tabindex="-1">info() <a class="header-anchor" href="#info" aria-label="Permalink to “info()”">​</a></h5><blockquote><p><strong>info</strong>(<code>message</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L30" target="_blank" rel="noreferrer">HttpSignaling.ts:30</a></p><h6 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="message-1" tabindex="-1">message <a class="header-anchor" href="#message-1" aria-label="Permalink to “message”">​</a></h6><p><code>string</code></p><h6 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><h5 id="warn" tabindex="-1">warn() <a class="header-anchor" href="#warn" aria-label="Permalink to “warn()”">​</a></h5><blockquote><p><strong>warn</strong>(<code>message</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/HttpSignaling.ts#L31" target="_blank" rel="noreferrer">HttpSignaling.ts:31</a></p><h6 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="message-2" tabindex="-1">message <a class="header-anchor" href="#message-2" aria-label="Permalink to “message”">​</a></h6><p><code>string</code></p><h6 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><hr><h3 id="udpports" tabindex="-1">UdpPorts <a class="header-anchor" href="#udpports" aria-label="Permalink to “UdpPorts”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L16" target="_blank" rel="noreferrer">udpPorts.ts:16</a></p><p>What a <code>server-udp-ports</code> setting says.</p><h4 id="properties-10" tabindex="-1">Properties <a class="header-anchor" href="#properties-10" aria-label="Permalink to “Properties”">​</a></h4><h5 id="local" tabindex="-1">local? <a class="header-anchor" href="#local" aria-label="Permalink to “local?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>local?</strong>: <a href="#portrange"><code>PortRange</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L18" target="_blank" rel="noreferrer">udpPorts.ts:18</a></p><p>The local ports WebRTC may allocate, or undefined to leave it to the operating system.</p><h5 id="mappings" tabindex="-1">mappings <a class="header-anchor" href="#mappings" aria-label="Permalink to “mappings”">​</a></h5><blockquote><p><code>readonly</code> <strong>mappings</strong>: readonly <a href="#portmapping"><code>PortMapping</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L20" target="_blank" rel="noreferrer">udpPorts.ts:20</a></p><p>Mappings to advertise in answers, in the order they were written.</p><hr><h3 id="verifiedidentity" tabindex="-1">VerifiedIdentity <a class="header-anchor" href="#verifiedidentity" aria-label="Permalink to “VerifiedIdentity”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L137" target="_blank" rel="noreferrer">NetherNetIdentity.ts:137</a></p><p>What <a href="#verifyselfsignedidentity">verifySelfSignedIdentity</a> found in a description it accepted.</p><h4 id="properties-11" tabindex="-1">Properties <a class="header-anchor" href="#properties-11" aria-label="Permalink to “Properties”">​</a></h4><h5 id="description" tabindex="-1">description <a class="header-anchor" href="#description" aria-label="Permalink to “description”">​</a></h5><blockquote><p><code>readonly</code> <strong>description</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L143" target="_blank" rel="noreferrer">NetherNetIdentity.ts:143</a></p><p>The description without <code>a=identity</code>, ready for WebRTC.</p><h5 id="domain-1" tabindex="-1">domain <a class="header-anchor" href="#domain-1" aria-label="Permalink to “domain”">​</a></h5><blockquote><p><code>readonly</code> <strong>domain</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L141" target="_blank" rel="noreferrer">NetherNetIdentity.ts:141</a></p><p>The domain the identity names, which a player may be shown.</p><h5 id="publickey" tabindex="-1">publicKey <a class="header-anchor" href="#publickey" aria-label="Permalink to “publicKey”">​</a></h5><blockquote><p><code>readonly</code> <strong>publicKey</strong>: <code>KeyObject</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L139" target="_blank" rel="noreferrer">NetherNetIdentity.ts:139</a></p><p>The identity&#39;s public key, from the token&#39;s <code>cpk</code> claim.</p><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to “Type Aliases”">​</a></h2><h3 id="identitykeyformat" tabindex="-1">IdentityKeyFormat <a class="header-anchor" href="#identitykeyformat" aria-label="Permalink to “IdentityKeyFormat”">​</a></h3><blockquote><p><strong>IdentityKeyFormat</strong> = <code>&quot;jwk&quot;</code> | <code>&quot;der&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L25" target="_blank" rel="noreferrer">NetherNetIdentity.ts:25</a></p><p>How an identity writes its public key into the token&#39;s <code>cpk</code> claim.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><h3 id="bedrock-curve" tabindex="-1">BEDROCK_CURVE <a class="header-anchor" href="#bedrock-curve" aria-label="Permalink to “BEDROCK_CURVE”">​</a></h3><blockquote><p><code>const</code> <strong>BEDROCK_CURVE</strong>: <code>&quot;secp384r1&quot;</code> = <code>&#39;secp384r1&#39;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/es384.ts#L6" target="_blank" rel="noreferrer">es384.ts:6</a></p><p>The curve Bedrock signs with: the login chain, the encryption handshake and NetherNet identities.</p><hr><h3 id="lan-advertisement-version" tabindex="-1">LAN_ADVERTISEMENT_VERSION <a class="header-anchor" href="#lan-advertisement-version" aria-label="Permalink to “LAN_ADVERTISEMENT_VERSION”">​</a></h3><blockquote><p><code>const</code> <strong>LAN_ADVERTISEMENT_VERSION</strong>: <code>7</code> = <code>7</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L5" target="_blank" rel="noreferrer">LanAdvertisement.ts:5</a></p><p>The advertisement layout Bedrock Dedicated Server 1.26.51 answers LAN discovery with.</p><hr><h3 id="nethernet-lan-port" tabindex="-1">NETHERNET_LAN_PORT <a class="header-anchor" href="#nethernet-lan-port" aria-label="Permalink to “NETHERNET_LAN_PORT”">​</a></h3><blockquote><p><code>const</code> <strong>NETHERNET_LAN_PORT</strong>: <code>7551</code> = <code>7551</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetDefaults.ts#L2" target="_blank" rel="noreferrer">NetherNetDefaults.ts:2</a></p><p>The UDP port NetherNet LAN discovery and signaling use. The protocol fixes it; npm <code>nethernet</code> binds it.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><h3 id="adaptpeerconnections" tabindex="-1">adaptPeerConnections() <a class="header-anchor" href="#adaptpeerconnections" aria-label="Permalink to “adaptPeerConnections()”">​</a></h3><blockquote><p><strong>adaptPeerConnections</strong>(<code>holder</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/peerConnections.ts#L66" target="_blank" rel="noreferrer">peerConnections.ts:66</a></p><p>Fits the werift peer connections <code>nethernet</code> 1.1.2 builds to the werift the workspace runs.</p><p><code>nethernet</code> pins werift 0.24.4 and works around two of its bugs; the workspace overrides werift to a release that fixes them, and both workarounds misfire there:</p><ul><li>Its <code>createDataChannel</code> sets the unordered bit on the channel&#39;s queued <code>DATA_CHANNEL_OPEN</code>, which werift 0.24.4 left out. Werift 0.26 sends the bit itself and no longer queues the open where the workaround looks, so creating an unordered channel threw. Werift&#39;s own method is called instead.</li><li>It turns werift&#39;s default Google STUN server off by assigning <code>stunServer</code>, a property werift 0.27 made read-only, so every answer waited on a STUN query again. <code>iceUseDefaultStunServer</code> turns it off.</li></ul><p>The native <code>@roamhq/wrtc</code> backend has neither workaround and is left as it is.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="holder" tabindex="-1">holder <a class="header-anchor" href="#holder" aria-label="Permalink to “holder”">​</a></h5><p><code>object</code></p><p>A <code>nethernet</code> <code>Server</code> or <code>Client</code> that has not been configured yet, before it negotiates any peer.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When the holder has no backend in the shape this expects, or the backend was already wrapped, which would hide <code>nethernet</code>&#39;s own class.</p><hr><h3 id="canonicalfingerprints" tabindex="-1">canonicalFingerprints() <a class="header-anchor" href="#canonicalfingerprints" aria-label="Permalink to “canonicalFingerprints()”">​</a></h3><blockquote><p><strong>canonicalFingerprints</strong>(<code>fingerprints</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L19" target="_blank" rel="noreferrer">NetherNetIdentity.ts:19</a></p><p>The fingerprints as canonical JSON: keys in code point order, no whitespace. The client rebuilds these exact bytes from the answer&#39;s <code>a=fingerprint</code> lines to check the signature.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="fingerprints" tabindex="-1">fingerprints <a class="header-anchor" href="#fingerprints" aria-label="Permalink to “fingerprints”">​</a></h5><p>readonly <a href="#sdpfingerprint"><code>SdpFingerprint</code></a>[]</p><p>The answer&#39;s fingerprints, in SDP order.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="compactes384" tabindex="-1">compactEs384() <a class="header-anchor" href="#compactes384" aria-label="Permalink to “compactEs384()”">​</a></h3><blockquote><p><strong>compactEs384</strong>(<code>header</code>, <code>payload</code>, <code>privateKey</code>): <code>Promise</code>&lt;<code>string</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/es384.ts#L18" target="_blank" rel="noreferrer">es384.ts:18</a></p><p>A compact ES384 JWS (a JWT, when the payload is a claim set): <code>header.payload.signature</code>, signed by <code>jose</code>.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="header" tabindex="-1">header <a class="header-anchor" href="#header" aria-label="Permalink to “header”">​</a></h5><p><code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;&gt;</p><p>Header fields besides <code>alg</code>, such as <code>x5u</code>.</p><h5 id="payload" tabindex="-1">payload <a class="header-anchor" href="#payload" aria-label="Permalink to “payload”">​</a></h5><p><code>unknown</code></p><p>The JSON payload.</p><h5 id="privatekey" tabindex="-1">privateKey <a class="header-anchor" href="#privatekey" aria-label="Permalink to “privateKey”">​</a></h5><p><code>KeyObject</code></p><p>A P-384 private key.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>string</code>&gt;</p><hr><h3 id="constrainiceports" tabindex="-1">constrainIcePorts() <a class="header-anchor" href="#constrainiceports" aria-label="Permalink to “constrainIcePorts()”">​</a></h3><blockquote><p><strong>constrainIcePorts</strong>(<code>server</code>, <code>range</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/constrainIcePorts.ts#L13" target="_blank" rel="noreferrer">constrainIcePorts.ts:13</a></p><p>Makes every peer connection a <code>nethernet</code> <code>Server</code> builds take its UDP ports from <code>range</code>.</p><p>Werift, <code>nethernet</code>&#39;s default backend, honors <code>icePortRange</code>; the optional native backend ignores it.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="server" tabindex="-1">server <a class="header-anchor" href="#server" aria-label="Permalink to “server”">​</a></h5><p><code>object</code></p><p>The <code>nethernet</code> <code>Server</code>, before it negotiates any peer.</p><h5 id="range" tabindex="-1">range <a class="header-anchor" href="#range" aria-label="Permalink to “range”">​</a></h5><p><a href="#portrange"><code>PortRange</code></a></p><p>The ports to allocate from, at least two.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>When the server does not hold a backend in the shape this expects.</p><hr><h3 id="decodejoinstatus" tabindex="-1">decodeJoinStatus() <a class="header-anchor" href="#decodejoinstatus" aria-label="Permalink to “decodeJoinStatus()”">​</a></h3><blockquote><p><strong>decodeJoinStatus</strong>(<code>body</code>): <a href="#nethernetstatus"><code>NetherNetStatus</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L39" target="_blank" rel="noreferrer">NetherNetStatus.ts:39</a></p><p>Reads a <code>GET /v1/join</code> body back into the status.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="body" tabindex="-1">body <a class="header-anchor" href="#body" aria-label="Permalink to “body”">​</a></h5><p><code>string</code></p><p>The JSON the server answered with.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a></p><h4 id="throws-2" tabindex="-1">Throws <a class="header-anchor" href="#throws-2" aria-label="Permalink to “Throws”">​</a></h4><p>When a field is missing or has the wrong type.</p><hr><h3 id="decodelanadvertisement" tabindex="-1">decodeLanAdvertisement() <a class="header-anchor" href="#decodelanadvertisement" aria-label="Permalink to “decodeLanAdvertisement()”">​</a></h3><blockquote><p><strong>decodeLanAdvertisement</strong>(<code>buffer</code>): <a href="#lanadvertisement"><code>LanAdvertisement</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L69" target="_blank" rel="noreferrer">LanAdvertisement.ts:69</a></p><p>Decodes an advertisement in layout <a href="#lan-advertisement-version">LAN_ADVERTISEMENT_VERSION</a>.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="buffer" tabindex="-1">buffer <a class="header-anchor" href="#buffer" aria-label="Permalink to “buffer”">​</a></h5><p><code>Buffer</code></p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><a href="#lanadvertisement"><code>LanAdvertisement</code></a></p><h4 id="throws-3" tabindex="-1">Throws <a class="header-anchor" href="#throws-3" aria-label="Permalink to “Throws”">​</a></h4><p>When the buffer carries another layout version or ends early.</p><hr><h3 id="describecandidates" tabindex="-1">describeCandidates() <a class="header-anchor" href="#describecandidates" aria-label="Permalink to “describeCandidates()”">​</a></h3><blockquote><p><strong>describeCandidates</strong>(<code>description</code>): <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/tracePeerConnection.ts#L4" target="_blank" rel="noreferrer">tracePeerConnection.ts:4</a></p><p>The candidates a description lists, as <code>address:port type</code>, for a log line.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="description-1" tabindex="-1">description <a class="header-anchor" href="#description-1" aria-label="Permalink to “description”">​</a></h5><p><code>string</code></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code>[]</p><hr><h3 id="detachedes384" tabindex="-1">detachedEs384() <a class="header-anchor" href="#detachedes384" aria-label="Permalink to “detachedEs384()”">​</a></h3><blockquote><p><strong>detachedEs384</strong>(<code>payload</code>, <code>privateKey</code>): <code>Promise</code>&lt;<code>string</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/es384.ts#L33" target="_blank" rel="noreferrer">es384.ts:33</a></p><p>A detached ES384 JWS over exact payload bytes (RFC 7515 appendix F): <code>header..signature</code>. The verifier rebuilds the payload itself, so its bytes must be the canonical ones it will build.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="payload-1" tabindex="-1">payload <a class="header-anchor" href="#payload-1" aria-label="Permalink to “payload”">​</a></h5><p><code>string</code></p><p>The payload bytes, signed as given.</p><h5 id="privatekey-1" tabindex="-1">privateKey <a class="header-anchor" href="#privatekey-1" aria-label="Permalink to “privateKey”">​</a></h5><p><code>KeyObject</code></p><p>A P-384 private key.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>string</code>&gt;</p><hr><h3 id="encodelanadvertisement" tabindex="-1">encodeLanAdvertisement() <a class="header-anchor" href="#encodelanadvertisement" aria-label="Permalink to “encodeLanAdvertisement()”">​</a></h3><blockquote><p><strong>encodeLanAdvertisement</strong>(<code>advertisement</code>): <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L46" target="_blank" rel="noreferrer">LanAdvertisement.ts:46</a></p><p>Encodes the advertisement in layout <a href="#lan-advertisement-version">LAN_ADVERTISEMENT_VERSION</a>: a version byte, then varint-prefixed strings, zigzag varints and booleans in a fixed order.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="advertisement" tabindex="-1">advertisement <a class="header-anchor" href="#advertisement" aria-label="Permalink to “advertisement”">​</a></h5><p><a href="#lanadvertisement"><code>LanAdvertisement</code></a></p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>Buffer</code></p><hr><h3 id="exchangeoffer" tabindex="-1">exchangeOffer() <a class="header-anchor" href="#exchangeoffer" aria-label="Permalink to “exchangeOffer()”">​</a></h3><blockquote><p><strong>exchangeOffer</strong>(<code>address</code>, <code>networkId</code>, <code>offer</code>, <code>signal?</code>): <code>Promise</code>&lt;<code>string</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/joinByAddress.ts#L58" target="_blank" rel="noreferrer">joinByAddress.ts:58</a></p><p>Trades a complete SDP offer for the server&#39;s complete answer, the one request a client sends per attempt.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="address-1" tabindex="-1">address <a class="header-anchor" href="#address-1" aria-label="Permalink to “address”">​</a></h5><p><a href="#signalingaddress"><code>SignalingAddress</code></a></p><p>The server&#39;s host and game port.</p><h5 id="networkid" tabindex="-1">networkId <a class="header-anchor" href="#networkid" aria-label="Permalink to “networkId”">​</a></h5><p><code>bigint</code></p><p>The client&#39;s own network ID.</p><h5 id="offer" tabindex="-1">offer <a class="header-anchor" href="#offer" aria-label="Permalink to “offer”">​</a></h5><p><code>string</code></p><p>The offer, with every candidate and the client&#39;s <code>a=identity</code>.</p><h5 id="signal-1" tabindex="-1">signal? <a class="header-anchor" href="#signal-1" aria-label="Permalink to “signal?”">​</a></h5><p><code>AbortSignal</code></p><p>Aborts the request.</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>string</code>&gt;</p><p>The answer.</p><h4 id="throws-4" tabindex="-1">Throws <a class="header-anchor" href="#throws-4" aria-label="Permalink to “Throws”">​</a></h4><p>When the server answers anything but 2xx.</p><hr><h3 id="joinstatusjson" tabindex="-1">joinStatusJson() <a class="header-anchor" href="#joinstatusjson" aria-label="Permalink to “joinStatusJson()”">​</a></h3><blockquote><p><strong>joinStatusJson</strong>(<code>status</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetStatus.ts#L23" target="_blank" rel="noreferrer">NetherNetStatus.ts:23</a></p><p>The <code>GET /v1/join</code> body: the status under the field names Bedrock Dedicated Server 1.26.51 answers with, in its order.</p><h4 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status-2" tabindex="-1">status <a class="header-anchor" href="#status-2" aria-label="Permalink to “status”">​</a></h5><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a></p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="lanadvertisementof" tabindex="-1">lanAdvertisementOf() <a class="header-anchor" href="#lanadvertisementof" aria-label="Permalink to “lanAdvertisementOf()”">​</a></h3><blockquote><p><strong>lanAdvertisementOf</strong>(<code>status</code>, <code>onlineMode</code>, <code>nonce</code>): <a href="#lanadvertisement"><code>LanAdvertisement</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/LanAdvertisement.ts#L32" target="_blank" rel="noreferrer">LanAdvertisement.ts:32</a></p><p>The advertisement for a server.</p><h4 id="parameters-17" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-17" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status-3" tabindex="-1">status <a class="header-anchor" href="#status-3" aria-label="Permalink to “status”">​</a></h5><p><a href="#nethernetstatus"><code>NetherNetStatus</code></a></p><p>What every NetherNet client is told about the server.</p><h5 id="onlinemode" tabindex="-1">onlineMode <a class="header-anchor" href="#onlinemode" aria-label="Permalink to “onlineMode”">​</a></h5><p><code>boolean</code></p><p>Whether the server requires Xbox Live sign-in.</p><h5 id="nonce-1" tabindex="-1">nonce <a class="header-anchor" href="#nonce-1" aria-label="Permalink to “nonce”">​</a></h5><p><code>string</code></p><p>This server start&#39;s token.</p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><a href="#lanadvertisement"><code>LanAdvertisement</code></a></p><hr><h3 id="parseudpports" tabindex="-1">parseUdpPorts() <a class="header-anchor" href="#parseudpports" aria-label="Permalink to “parseUdpPorts()”">​</a></h3><blockquote><p><strong>parseUdpPorts</strong>(<code>setting</code>): <a href="#udpports"><code>UdpPorts</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L46" target="_blank" rel="noreferrer">udpPorts.ts:46</a></p><p>Reads Bedrock Dedicated Server&#39;s <code>server-udp-ports</code> syntax: comma-separated entries, each either <code>internal</code> or <code>start-end</code> (a local port range for WebRTC), or <code>[ip:]external[-external]:internal[-internal]</code> (a mapping to advertise, its two sides the same length). An IPv6 address goes in brackets.</p><h4 id="parameters-18" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-18" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="setting" tabindex="-1">setting <a class="header-anchor" href="#setting" aria-label="Permalink to “setting”">​</a></h5><p><code>string</code></p><p>The setting, or an empty string for none.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><a href="#udpports"><code>UdpPorts</code></a></p><h4 id="throws-5" tabindex="-1">Throws <a class="header-anchor" href="#throws-5" aria-label="Permalink to “Throws”">​</a></h4><p>For an entry in neither form, ports out of range, or mismatched mapping lengths; and for local ranges werift cannot allocate from: more than one, or a single port.</p><hr><h3 id="probejoin" tabindex="-1">probeJoin() <a class="header-anchor" href="#probejoin" aria-label="Permalink to “probeJoin()”">​</a></h3><blockquote><p><strong>probeJoin</strong>(<code>address</code>, <code>signal?</code>): <code>Promise</code>&lt;<a href="#joinprobe"><code>JoinProbe</code></a> | <code>undefined</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/joinByAddress.ts#L41" target="_blank" rel="noreferrer">joinByAddress.ts:41</a></p><p>Asks whether the server speaks NetherNet, as a client does before it joins by address: any 2xx from <code>GET /v1/join</code> means yes, whatever the body says.</p><h4 id="parameters-19" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-19" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="address-2" tabindex="-1">address <a class="header-anchor" href="#address-2" aria-label="Permalink to “address”">​</a></h5><p><a href="#signalingaddress"><code>SignalingAddress</code></a></p><p>The server&#39;s host and game port.</p><h5 id="signal-2" tabindex="-1">signal? <a class="header-anchor" href="#signal-2" aria-label="Permalink to “signal?”">​</a></h5><p><code>AbortSignal</code></p><p>Aborts the request.</p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="#joinprobe"><code>JoinProbe</code></a> | <code>undefined</code>&gt;</p><p>What the server said, or undefined when it does not speak NetherNet there.</p><h4 id="throws-6" tabindex="-1">Throws <a class="header-anchor" href="#throws-6" aria-label="Permalink to “Throws”">​</a></h4><p>When a 2xx body is present but is not a join status.</p><hr><h3 id="sdpfingerprints" tabindex="-1">sdpFingerprints() <a class="header-anchor" href="#sdpfingerprints" aria-label="Permalink to “sdpFingerprints()”">​</a></h3><blockquote><p><strong>sdpFingerprints</strong>(<code>sdp</code>): <a href="#sdpfingerprint"><code>SdpFingerprint</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/sdp.ts#L23" target="_blank" rel="noreferrer">sdp.ts:23</a></p><p>Every <code>a=fingerprint</code> in a description, in the order they appear.</p><h4 id="parameters-20" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-20" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sdp" tabindex="-1">sdp <a class="header-anchor" href="#sdp" aria-label="Permalink to “sdp”">​</a></h5><p><code>string</code></p><p>The session description.</p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><a href="#sdpfingerprint"><code>SdpFingerprint</code></a>[]</p><hr><h3 id="tracepeerconnection" tabindex="-1">tracePeerConnection() <a class="header-anchor" href="#tracepeerconnection" aria-label="Permalink to “tracePeerConnection()”">​</a></h3><blockquote><p><strong>tracePeerConnection</strong>(<code>rtcConnection</code>, <code>log</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/tracePeerConnection.ts#L33" target="_blank" rel="noreferrer">tracePeerConnection.ts:33</a></p><p>Reports a peer connection&#39;s ICE and connection states as they change, and the candidate pair ICE settles on: where a join that never finishes stopped. A pair that never connects usually means the server&#39;s UDP ports are not reachable from the client, as behind a firewall that opens only the game port.</p><p>Werift, <code>nethernet</code>&#39;s default backend, exposes these as events; with another backend this reports nothing.</p><h4 id="parameters-21" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-21" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="rtcconnection" tabindex="-1">rtcConnection <a class="header-anchor" href="#rtcconnection" aria-label="Permalink to “rtcConnection”">​</a></h5><p><code>unknown</code></p><p>The peer connection <code>nethernet</code> built.</p><h5 id="log" tabindex="-1">log <a class="header-anchor" href="#log" aria-label="Permalink to “log”">​</a></h5><p>(<code>line</code>) =&gt; <code>void</code></p><p>Where each change goes, as one line.</p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="verifiesdetachedes384" tabindex="-1">verifiesDetachedEs384() <a class="header-anchor" href="#verifiesdetachedes384" aria-label="Permalink to “verifiesDetachedEs384()”">​</a></h3><blockquote><p><strong>verifiesDetachedEs384</strong>(<code>jws</code>, <code>payload</code>, <code>publicKey</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/es384.ts#L44" target="_blank" rel="noreferrer">es384.ts:44</a></p><p>Whether <code>jws</code> is a detached ES384 signature over <code>payload</code> by <code>publicKey</code>.</p><h4 id="parameters-22" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-22" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="jws" tabindex="-1">jws <a class="header-anchor" href="#jws" aria-label="Permalink to “jws”">​</a></h5><p><code>string</code></p><p>The detached JWS, <code>header..signature</code>.</p><h5 id="payload-2" tabindex="-1">payload <a class="header-anchor" href="#payload-2" aria-label="Permalink to “payload”">​</a></h5><p><code>string</code></p><p>The payload bytes the signer should have signed.</p><h5 id="publickey-1" tabindex="-1">publicKey <a class="header-anchor" href="#publickey-1" aria-label="Permalink to “publicKey”">​</a></h5><p><code>KeyObject</code></p><p>The P-384 key it should verify against.</p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><hr><h3 id="verifyselfsignedidentity" tabindex="-1">verifySelfSignedIdentity() <a class="header-anchor" href="#verifyselfsignedidentity" aria-label="Permalink to “verifySelfSignedIdentity()”">​</a></h3><blockquote><p><strong>verifySelfSignedIdentity</strong>(<code>description</code>, <code>nowMs?</code>): <code>Promise</code>&lt;<a href="#verifiedidentity"><code>VerifiedIdentity</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/NetherNetIdentity.ts#L168" target="_blank" rel="noreferrer">NetherNetIdentity.ts:168</a></p><p>Checks a self-signed <code>a=identity</code> the way a NetherNet client checks a server&#39;s: the token is signed by the key in its own <code>cpk</code> claim and not expired, and the detached signature covers this description&#39;s fingerprints. Offline clients sign their offers the same way; an online client&#39;s token is signed by the authorization service instead, which this does not check.</p><h4 id="parameters-23" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-23" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="description-2" tabindex="-1">description <a class="header-anchor" href="#description-2" aria-label="Permalink to “description”">​</a></h5><p><code>string</code></p><p>The SDP description carrying <code>a=identity</code>.</p><h5 id="nowms" tabindex="-1">nowMs? <a class="header-anchor" href="#nowms" aria-label="Permalink to “nowMs?”">​</a></h5><p><code>number</code> = <code>...</code></p><p>The clock, in milliseconds since the epoch.</p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="#verifiedidentity"><code>VerifiedIdentity</code></a>&gt;</p><h4 id="throws-7" tabindex="-1">Throws <a class="header-anchor" href="#throws-7" aria-label="Permalink to “Throws”">​</a></h4><p>When the identity is missing, malformed, expired or does not verify.</p><hr><h3 id="withmappedcandidates" tabindex="-1">withMappedCandidates() <a class="header-anchor" href="#withmappedcandidates" aria-label="Permalink to “withMappedCandidates()”">​</a></h3><blockquote><p><strong>withMappedCandidates</strong>(<code>answer</code>, <code>mappings</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/udpPorts.ts#L92" target="_blank" rel="noreferrer">udpPorts.ts:92</a></p><p>The answer with a server-reflexive candidate added for every host candidate a mapping covers: the external address (or the candidate&#39;s own) and the external port its internal port maps to. That is how a client outside the network learns where to reach a server behind NAT.</p><h4 id="parameters-24" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-24" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="answer-1" tabindex="-1">answer <a class="header-anchor" href="#answer-1" aria-label="Permalink to “answer”">​</a></h5><p><code>string</code></p><p>The SDP answer, with its candidates.</p><h5 id="mappings-1" tabindex="-1">mappings <a class="header-anchor" href="#mappings-1" aria-label="Permalink to “mappings”">​</a></h5><p>readonly <a href="#portmapping"><code>PortMapping</code></a>[]</p><p>The mappings to advertise.</p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="withsessionattribute" tabindex="-1">withSessionAttribute() <a class="header-anchor" href="#withsessionattribute" aria-label="Permalink to “withSessionAttribute()”">​</a></h3><blockquote><p><strong>withSessionAttribute</strong>(<code>sdp</code>, <code>attribute</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/sdp.ts#L43" target="_blank" rel="noreferrer">sdp.ts:43</a></p><p>The description with one session-level attribute added: after every other session-level line and before the first media section, which is where NetherNet expects <code>a=identity</code>.</p><h4 id="parameters-25" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-25" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sdp-1" tabindex="-1">sdp <a class="header-anchor" href="#sdp-1" aria-label="Permalink to “sdp”">​</a></h5><p><code>string</code></p><p>The session description.</p><h5 id="attribute" tabindex="-1">attribute <a class="header-anchor" href="#attribute" aria-label="Permalink to “attribute”">​</a></h5><p><code>string</code></p><p>The attribute line, such as <code>a=identity:…</code>.</p><h4 id="returns-27" tabindex="-1">Returns <a class="header-anchor" href="#returns-27" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="withoutidentity" tabindex="-1">withoutIdentity() <a class="header-anchor" href="#withoutidentity" aria-label="Permalink to “withoutIdentity()”">​</a></h3><blockquote><p><strong>withoutIdentity</strong>(<code>sdp</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/5078937addea254f719a98034ca38bca37875eb0/packages/nethernet/src/sdp.ts#L34" target="_blank" rel="noreferrer">sdp.ts:34</a></p><p>The description with every <code>a=identity</code> line removed. The identity is NetherNet&#39;s, checked before the description reaches WebRTC, which does not know the attribute.</p><h4 id="parameters-26" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-26" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sdp-2" tabindex="-1">sdp <a class="header-anchor" href="#sdp-2" aria-label="Permalink to “sdp”">​</a></h5><p><code>string</code></p><p>The session description.</p><h4 id="returns-28" tabindex="-1">Returns <a class="header-anchor" href="#returns-28" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p>`,622)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};